const wanted = String($('Settings').first().json.technologies || '')
  .split(',').map(s => s.trim()).filter(Boolean);
const domains = [...new Set($input.all()
  .filter(i => i.json.domain && !i.json.scanned_at)
  .map(i => String(i.json.domain).trim()))].slice(0, 200);
if (!domains.length) return [];
return [{ json: { domains, matchTechnologies: wanted } }];

return $input.all().map(({ json: r }) => {
  const matched = Object.entries(r.matches || {}).filter(([, v]) => v).map(([k]) => k);
  return { json: {
    domain: r.input || r.domain,
    match: r.matchesAny ? 'yes' : 'no',
    matched_technologies: matched.join(', '),
    technologies: (r.technologyNames || []).join(', '),
    email_providers: (r.emailProviders || []).join(', '),
    technology_count: r.technologyCount ?? 0,
    status: r.ok ? 'ok' : (r.error || 'unreachable'),
    scanned_at: r.scannedAt || new Date().toISOString(),
  }};
});

const hot = $input.all().map(i => i.json).filter(r => r.match === 'yes');
if (!hot.length) return [];
const lines = hot.slice(0, 30).map(r => `• ${r.domain}: ${r.matched_technologies}`);
const more = hot.length > 30 ? `\n…and ${hot.length - 30} more in the sheet.` : '';
return [{ json: { text: `:dart: ${hot.length} new matching lead(s)\n${lines.join('\n')}${more}` } }];
